131	/**
132	 * @brief Decode the length of an HCI H4 packet and check it's complete
133	 * @details Decodes packet length according to Bluetooth spec v5.4 Vol 4 Part E
134	 * @param buf	Pointer to a HCI packet buffer
135	 * @param buf_len	Bytes available in the buffer
136	 * @return Length of the complete HCI packet in bytes, -1 if cannot find an HCI
137	 *         packet, 0 if more data required.
138	 */
139	static int32_t hci_packet_complete(const uint8_t *buf, uint16_t buf_len)
140	{
141		uint16_t payload_len = 0;
142		const uint8_t type = buf[0];
143		uint8_t header_len = sizeof(type);
144		const uint8_t *hdr = &buf[sizeof(type)];
145	
146		switch (type) {
147		case BT_HCI_H4_CMD: {
148			if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
149				return 0;
150			}
151			const struct bt_hci_cmd_hdr *cmd = (const struct bt_hci_cmd_hdr *)hdr;
152	
153			/* Parameter Total Length */
154			payload_len = cmd->param_len;
155			header_len += BT_HCI_CMD_HDR_SIZE;
156			break;
157		}
158		case BT_HCI_H4_ACL: {
159			if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
160				return 0;
161			}
162			const struct bt_hci_acl_hdr *acl = (const struct bt_hci_acl_hdr *)hdr;
163	
164			/* Data Total Length */
165			payload_len = sys_le16_to_cpu(acl->len);
166			header_len += BT_HCI_ACL_HDR_SIZE;
167			break;
168		}
169		case BT_HCI_H4_SCO: {
170			if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
171				return 0;
172			}
173			const struct bt_hci_sco_hdr *sco = (const struct bt_hci_sco_hdr *)hdr;
174	
175			/* Data_Total_Length */
176			payload_len = sco->len;
177			header_len += BT_HCI_SCO_HDR_SIZE;
178			break;
179		}
180		case BT_HCI_H4_EVT: {
181			if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
182				return 0;
183			}
184			const struct bt_hci_evt_hdr *evt = (const struct bt_hci_evt_hdr *)hdr;
185	
186			/* Parameter Total Length */
187			payload_len = evt->len;
188			header_len += BT_HCI_EVT_HDR_SIZE;
189			break;
190		}
191		case BT_HCI_H4_ISO: {
192			if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
193				return 0;
194			}
195			const struct bt_hci_iso_hdr *iso = (const struct bt_hci_iso_hdr *)hdr;
196	
197			/* ISO_Data_Load_Length parameter */
198			payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
199			header_len += BT_HCI_ISO_HDR_SIZE;
200			break;
201		}
202		/* If no valid packet type found */
203		default:
204			LOG_WRN("Unknown packet type 0x%02x", type);
205			return -1;
206		}
207	
208		/* Request more data */
209		if (buf_len < header_len + payload_len) {
210			return 0;
211		}
212	
213		return (int32_t)header_len + payload_len;
214	}
