225	static void h4_rx_thread(void *p1, void *p2, void *p3)
226	{
227		const struct device *dev = p1;
228		struct h4_data *h4 = dev->data;
229	
230		ARG_UNUSED(p2);
231		ARG_UNUSED(p3);
232	
233		LOG_DBG("started");
234	
235		ssize_t frame_size = 0;
236	
237		while (1) {
238			struct net_buf *buf;
239			size_t buf_tailroom;
240			size_t buf_add_len;
241			ssize_t len;
242			const uint8_t *frame_start = h4->frame;
243	
244	#if 1
245			if (!h4_ready(h4)) {
246				usleep(1000);
247				continue;
248			}
249	#endif
250	
251			LOG_DBG("calling read()");
252	
253			len = read(h4->fd, h4->frame + frame_size, sizeof(h4->frame) - frame_size);
254			if (len < 0) {
255				if (errno == EINTR) {
256					continue;
257				}
258	
259				if (len == -EAGAIN) {
260					usleep(500);
261					continue;
262				}
263	
264				LOG_ERR("Reading hci failed, errno %d", errno);
265				close(h4->fd);
266				h4->fd = -1;
267				return;
268			}
269	
270			frame_size += len;
271	
272			while (frame_size > 0) {
273				const uint8_t *buf_add;
274				const uint8_t packet_type = frame_start[0];
275				const int32_t decoded_len = hci_packet_complete(frame_start, frame_size);
276	
277				if (decoded_len == -1) {
278					LOG_ERR("HCI Packet type is invalid, length could not be decoded");
279					frame_size = 0; /* Drop buffer */
280					break;
281				}
282	
283				if (decoded_len == 0) {
284					if (frame_size == sizeof(h4->frame)) {
285						LOG_ERR("HCI Packet (%d bytes) is too big for frame (%d "
286							"bytes)",
287							decoded_len, sizeof(h4->frame));
288						frame_size = 0; /* Drop buffer */
289						break;
290					}
291					if (frame_start != h4->frame) {
292						memmove(h4->frame, frame_start, frame_size);
293					}
294					/* Read more */
295					break;
296				}
297	
298				buf_add = frame_start + sizeof(packet_type);
299				buf_add_len = decoded_len - sizeof(packet_type);
300	
301				buf = get_rx(frame_start);
302	
303				btsnoop_log_capture(1, (uint8_t *)frame_start, decoded_len);
304	
305				frame_size -= decoded_len;
306				frame_start += decoded_len;
307	
308				if (!buf) {
309					LOG_DBG("Discard adv report due to insufficient buf");
310					continue;
311				}
312	
313				buf_tailroom = net_buf_tailroom(buf);
314				if (buf_tailroom < buf_add_len) {
315					LOG_ERR("Not enough space in buffer %zu/%zu", buf_add_len,
316						buf_tailroom);
317					net_buf_unref(buf);
318					continue;
319				}
320	
321				net_buf_add_mem(buf, buf_add, buf_add_len);
322	
323				LOG_DBG("Calling bt_recv(%p)", buf);
324	
325				h4_data_dump("BT RX", packet_type, buf->data, buf_add_len);
326				h4->recv(dev, buf, h4->hci_data);
327			}
328		}
329	}
