141	void shell_hexdump_line(const struct shell *sh, unsigned int offset,
142				const uint8_t *data, size_t len)
143	{
144		__ASSERT_NO_MSG(sh);
145	
146		int i;
147	
148		shell_fprintf_normal(sh, "%08X: ", offset);
149	
150		for (i = 0; i < SHELL_HEXDUMP_BYTES_IN_LINE; i++) {
151			if (i > 0 && !(i % 8)) {
152				shell_fprintf_normal(sh, " ");
153			}
154	
155			if (i < len) {
156				shell_fprintf_normal(sh, "%02x ",
157						     data[i] & 0xFF);
158			} else {
159				shell_fprintf_normal(sh, "   ");
160			}
161		}
162	
163		shell_fprintf_normal(sh, "|");
164	
165		for (i = 0; i < SHELL_HEXDUMP_BYTES_IN_LINE; i++) {
166			if (i > 0 && !(i % 8)) {
167				shell_fprintf_normal(sh, " ");
168			}
169	
170			if (i < len) {
171				char c = data[i];
172	
173				shell_fprintf_normal(sh, "%c",
174						     isprint((int)c) != 0 ? c : '.');
175			} else {
176				shell_fprintf_normal(sh, " ");
177			}
178		}
179	
180		shell_print(sh, "|");
181	}
