183	void shell_hexdump(const struct shell *sh, const uint8_t *data, size_t len)
184	{
185		__ASSERT_NO_MSG(sh);
186	
187		const uint8_t *p = data;
188		size_t line_len;
189	
190		while (len) {
191			line_len = MIN(len, SHELL_HEXDUMP_BYTES_IN_LINE);
192	
193			shell_hexdump_line(sh, p - data, p, line_len);
194	
195			len -= line_len;
196			p += line_len;
197		}
198	}
