200	void shell_help(const struct shell *sh)
201	{
202		const struct shell_static_entry *pcmds = &sh->ctx->active_cmd;
203	
204	    shell_fprintf_normal(sh, "Help message\n");
205		shell_fprintf_info(sh, "\t%s mands:%d opts:%d help:%s\n",
206			   pcmds->syntax,
207			   pcmds->args.mandatory, pcmds->args.optional,
208			   pcmds->help);
209	
210		if (!pcmds->subcmd) {
211			return;
212		}
213	
214		pcmds = pcmds->subcmd->entry;
215		for (; pcmds && pcmds->syntax; pcmds++) {
216			shell_fprintf_info(sh, "\t%s mands:%d opts:%d help:%s\n",
217			       pcmds->syntax,
218			       pcmds->args.mandatory, pcmds->args.optional,
219			       pcmds->help);
220		}
221	}
222	
223	/* Function returning pointer to parent command matching requested syntax. */
224	static const struct shell_static_entry *root_cmd_find(const char *syntax)
225	{
226		TYPE_SECTION_FOREACH(const union shell_cmd_entry, shell_root_cmds, cmd) {
227			if (strcmp(syntax, cmd->entry->syntax) == 0) {
228				return cmd->entry;
229			}
230		}
231	
232		return NULL;
233	}
234	
235	static void cmds_show(const struct shell *sh)
236	{
237		TYPE_SECTION_FOREACH(const union shell_cmd_entry, shell_root_cmds, cmd) {
238			shell_fprintf_info(sh, "%s\t%s\n",
239				   cmd->entry->syntax, cmd->entry->help);
240		}
241	}
242	
243	static int execute_cmd(const struct shell *sh, size_t argc, char **argv)
244	{
245		const struct shell_static_entry *cmd;
246	
247		cmd = root_cmd_find(argv[0]);
248		if (!cmd) {
249			return -ENOEXEC;
250		}
251	
252		if (argc == 1) {
253			memcpy(&sh->ctx->active_cmd, cmd,
254			       sizeof(struct shell_static_entry));
255	
256			if (!cmd->handler) {
257				return 0;
258			}
259	
260			return cmd->handler(sh, argc, &argv[0]);
261		}
262	
263		cmd = cmd->subcmd->entry;
264		for (; cmd && cmd->syntax; cmd++) {
265			if (strcmp(argv[1], cmd->syntax)) {
266				continue;
267			}
268	
269			if (cmd->args.mandatory > argc - 1) {
270				shell_fprintf_info(sh, "cmd:%s Mands:%d opts:%d help:%s\n",
271				   	   cmd->syntax,
272				   	   cmd->args.mandatory, cmd->args.optional,
273				   	   cmd->help);
274				return 0;
275			}
276	
277			memcpy(&sh->ctx->active_cmd, cmd,
278			       sizeof(struct shell_static_entry));
279			return cmd->handler(sh, argc - 1, &argv[1]);
280		}
281	
282		return -ENOEXEC;
283	}
