286	
287	int main(int argc, char *argv[])
288	{
289		struct shell_ctx ctx = { 0 };
290		struct shell sh = { .ctx = &ctx };
291		int _argc = 0;
292		char* _argv[32];
293		char* buffer = NULL;
294		char* saveptr;
295		int ret = 0;
296		size_t len, size = 0;
297	
298		z_sys_init();
299	
300		while (1) {
301			printf("zblue> ");
302			fflush(stdout);
303	
304			memset(_argv, 0, sizeof(_argv));
305			len = getline(&buffer, &size, stdin);
306			if (-1 == len)
307				goto end;
308	
309			buffer[len] = '\0';
310			if (buffer[len - 1] == '\n')
311				buffer[len - 1] = '\0';
312	
313			if (buffer[0] == '!') {
314	#ifdef CONFIG_SYSTEM_SYSTEM
315				system(buffer + 1);
316	#endif
317				continue;
318			}
319	
320			saveptr = NULL;
321			char* tmpstr = buffer;
322	
323			while ((tmpstr = strtok_r(tmpstr, " ", &saveptr)) != NULL) {
324				_argv[_argc] = tmpstr;
325				_argc++;
326				tmpstr = NULL;
327			}
328	
329			if (_argc > 0) {
330				if (strcmp(_argv[0], "q") == 0) {
331					shell_fprintf_info(&sh, "Bye!\n");
332					ret = 0;
333					goto end;
334				} else if (strcmp(_argv[0], "help") == 0) {
335					cmds_show(&sh);
336				} else {
337					ret = execute_cmd(&sh, _argc, _argv);
338				}
339	
340				_argc = 0;
341			}
342		}
343	
344	return 0;
345	
346	end:
347		free(buffer);
348		if (ret)
349			cmds_show(&sh);
350	
351		return 0;
352	}
