		printf("zblue> ");
		fflush(stdout);

		memset(_argv, 0, sizeof(_argv));
		if (fgets(buffer, sizeof(buffer), stdin) == NULL)
			goto end;

		len = strlen(buffer);
		if (len > 0 && buffer[len - 1] == '\n')
			buffer[len - 1] = '\0';
		len = strlen(buffer);
		if (len > 0 && buffer[len - 1] == '\r')
			buffer[len - 1] = '\0';
